      ]
    }
  ],
  "business_context": [
    "فروش B2B با قراردادهای سالانه و فروش B2C مستقیم",
    "برنامهٔ رشد سالانهٔ ۲۵٪",
    "تخفیف‌ها به‌صورت دستی و بدون سقف رسمی ثبت می‌شوند"
  ]
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
  "tool": "compare_periods",
  "arguments": {
    "metrics": [
      "avg_deal_size"
    ],
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}
```

نتیجهٔ داده:
```json
{
  "revenue_m": {
    "prev": 34200,
    "curr": 27686,
    "change_pct": -19.0
  },
  "units": {
    "prev": 23700,
    "curr": 19186
  }
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
  "tool": "get_dataset",
  "arguments": {
    "name": "sales_funnel",
    "filters": {
      "region": "تهران",
      "period": "curr_month"
    }
  }
}
```

نتیجهٔ داده:
```json
{
  "funnel": {
    "leads": 677,
    "opportunities": 164,
    "proposals": 134,
    "deals": 37
  },
  "note": "اگر فرصت‌ها کم شده، مشکل ورودی قیف است؛ اگر تبدیل افت کرده، مشکل تیم فروش"
}
```

